    getComentariosPorPublicacion,
    getComentariosPorPerfil,
    getUsuarioActual,
    actualizarPerfil,
} from "../../Api";

const EditarPerfil = () => {
    const navigate = useNavigate();
    const [usuarioLogeado, setUsuarioLogeado] = useState(null);
    const [activeTab, setActiveTab] = useState('publicaciones');
    const [posts, setPosts] = useState([]);
    const [comentarios, setComentarios] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [selectedTablon, setSelectedTablon] = useState('');
    const [selectedDate, setSelectedDate] = useState('');

    // Estados para edición
    const [editandoNombre, setEditandoNombre] = useState(false);
    const [editandoDescripcion, setEditandoDescripcion] = useState(false);
    const [nuevoNombre, setNuevoNombre] = useState('');
    const [nuevaDescripcion, setNuevaDescripcion] = useState('');
    const [imagenPreview, setImagenPreview] = useState(null);
    const [guardando, setGuardando] = useState(false);

    // Estado para notificaciones
    const [notificacion, setNotificacion] = useState({
        visible: false,
        mensaje: '',
        tipo: 'success'
    });

    // Imagen por defecto
    const IMAGEN_DEFAULT = '/vision.svg';

    // =============================
    // SISTEMA DE NOTIFICACIONES
    // =============================
    const mostrarNotificacion = useCallback((mensaje, tipo = 'success') => {
        setNotificacion({ visible: true, mensaje, tipo });
        setTimeout(() => {
            setNotificacion({ visible: false, mensaje: '', tipo: 'success' });
        }, 3000);
    }, []);

    // =============================
    // FUNCIÓN CENTRALIZADA DE ACTUALIZACIÓN
    // =============================
    const actualizarPerfilYStorage = useCallback(async (datosActualizados) => {
        try {
            setGuardando(true);

            console.log("Actualizando perfil con datos:", datosActualizados);

            // 1. Enviar actualización al backend
            const perfilActualizado = await actualizarPerfil(
                usuarioLogeado.perfil.id, 
                datosActualizados
            );

            // 2. Actualizar estado local con los datos retornados del backend
            const usuarioActualizado = {
                ...usuarioLogeado,
                perfil: {
                    ...usuarioLogeado.perfil,
                    ...perfilActualizado
                }
            };

            // 3. Guardar en localStorage
            localStorage.setItem('usuarioLogeado', JSON.stringify(usuarioActualizado));

            // 4. Actualizar estado del componente
            setUsuarioLogeado(usuarioActualizado);

            console.log("Perfil actualizado exitosamente:", perfilActualizado);

            return { success: true, data: perfilActualizado };
        } catch (error) {
            console.error('Error al actualizar perfil:', error);
            return { 
                success: false, 
                error: error.message || 'Error desconocido al actualizar perfil'
            };
        } finally {
            setGuardando(false);
        }
    }, [usuarioLogeado]);

    // =============================
    // HELPERS
    // =============================
    const formatearFecha = useCallback((fecha) => {
        return new Date(fecha).toLocaleString("es-MX", {
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
        });
    }, []);

    const formatearPublicacion = useCallback((pub, perfil) => ({
        id: pub.id,
        perfilId: pub.perfil,
        author: pub.perfil_info?.nom_usuario || perfil.nom_usuario,
        avatar: pub.perfil_info?.foto_perfil || perfil.foto_perfil || IMAGEN_DEFAULT,
        date: formatearFecha(pub.fecha_pub),
        content: pub.texto,
        image: pub.fotos?.[0]?.ruta_foto || null,
        kudos: pub.like_pub,
        fecha_pub: pub.fecha_pub,
        tipo: 'publicacion'
    }), [formatearFecha]);

    const formatearComentario = useCallback((com, perfil) => ({
        id: com.id,
        publicacionId: com.publicacion,
        perfilId: com.perfil,
        author: com.perfil_info?.nom_usuario || perfil.nom_usuario,
        avatar: com.perfil_info?.foto_perfil || perfil.foto_perfil || IMAGEN_DEFAULT,
        text: com.texto,
        kudos: com.like_com,
        date: formatearFecha(com.fecha_com),
        fecha_com: com.fecha_com,
        tipo: 'comentario'
    }), [formatearFecha]);

    // =============================
    // VERIFICACIÓN DE AUTENTICACIÓN
    // =============================
    useEffect(() => {
        const usuario = getUsuarioActual();

        if (!usuario) {
            console.log("No hay usuario logeado, redirigiendo a /cuenta");
            navigate("/cuenta");
            return;
        }

        console.log("Usuario logeado:", usuario);
        setUsuarioLogeado(usuario);
        setNuevoNombre(usuario.perfil?.nom_usuario || '');
        setNuevaDescripcion(usuario.perfil?.biografia || '');
    }, [navigate]);

    // =============================
    // CARGA DE DATOS
    // =============================
    useEffect(() => {
        if (!usuarioLogeado?.perfil?.id) return;

        cargarPublicacionesYComentarios();
    }, [usuarioLogeado?.perfil?.id]);

    const cargarPublicacionesYComentarios = useCallback(async () => {
        if (!usuarioLogeado?.perfil?.id) {
            console.error("No hay usuario válido");
            return;
        }

        try {
            setLoading(true);
            setError(null);

            console.log("Cargando contenido del usuario ID:", usuarioLogeado.perfil.id);

            const [publicacionesData, comentariosData] = await Promise.all([
                getPublicacionesPorPerfil(usuarioLogeado.perfil.id),
                cargarComentariosDelUsuario()
            ]);

            const publicaciones = Array.isArray(publicacionesData)
                ? publicacionesData
                : publicacionesData.results || [];

            const publicacionesFormateadas = publicaciones.map(pub => 
                formatearPublicacion(pub, usuarioLogeado.perfil)
            );

            setPosts(publicacionesFormateadas);
            setComentarios(comentariosData);

            console.log(`${publicacionesFormateadas.length} publicaciones cargadas`);
            console.log(`${comentariosData.length} comentarios cargados`);

        } catch (err) {
            console.error("Error al cargar contenido:", err);
            setError("No se pudo cargar el contenido");
        } finally {
            setLoading(false);
        }
    }, [usuarioLogeado?.perfil, formatearPublicacion]);

    const cargarComentariosDelUsuario = useCallback(async () => {
        try {
            if (typeof getComentariosPorPerfil === 'function') {
                try {
                    const comentariosDelUsuario = await getComentariosPorPerfil(usuarioLogeado.perfil.id);
                    return comentariosDelUsuario.map(com => 
                        formatearComentario(com, usuarioLogeado.perfil)
                    );
                } catch (endpointError) {
                    console.warn("Endpoint por-perfil no disponible, usando fallback");
                }
            }

            const publicacionesData = await getPublicacionesPorPerfil(usuarioLogeado.perfil.id);
            const publicaciones = Array.isArray(publicacionesData)
                ? publicacionesData
                : publicacionesData.results || [];

            const todosLosComentarios = [];

            for (const post of publicaciones) {
                const comentariosPost = await getComentariosPorPublicacion(post.id);
                const comentariosDelUsuario = comentariosPost
                    .filter(com => com.perfil === usuarioLogeado.perfil.id)
                    .map(com => formatearComentario(com, usuarioLogeado.perfil));

                todosLosComentarios.push(...comentariosDelUsuario);
            }

            return todosLosComentarios;

        } catch (err) {
            console.error("Error al cargar comentarios:", err);
            return [];
        }
    }, [usuarioLogeado?.perfil, formatearComentario]);

    // =============================
    // FUNCIONES DE EDICIÓN
    // =============================

    // Cambiar imagen de perfil
    const handleCambiarImagen = (e) => {
        const file = e.target.files[0];
        if (!file) return;

        // Validar tipo de archivo
        if (!file.type.startsWith('image/')) {
            mostrarNotificacion('Por favor selecciona una imagen válida', 'error');
            return;
        }

        // Validar tamaño (máx 5MB)
        if (file.size > 5 * 1024 * 1024) {
            mostrarNotificacion('La imagen no debe superar 5MB', 'error');
            return;
        }

        // Crear preview
        const reader = new FileReader();
        reader.onloadend = () => {
            setImagenPreview(reader.result);
            guardarImagen(reader.result);
        };
        reader.readAsDataURL(file);
    };

    const guardarImagen = async (imagenBase64) => {
        const resultado = await actualizarPerfilYStorage({ 
            foto_perfil: imagenBase64 
        });

        if (resultado.success) {
            setImagenPreview(null);
            mostrarNotificacion('Imagen actualizada correctamente');
        } else {
            mostrarNotificacion(resultado.error, 'error');
        }
    };

    const handleEliminarImagen = async () => {
        if (!window.confirm('¿Estás seguro de eliminar tu foto de perfil?')) return;

        const resultado = await actualizarPerfilYStorage({ 
            foto_perfil: IMAGEN_DEFAULT 
        });

        if (resultado.success) {
            mostrarNotificacion('Imagen eliminada correctamente');
        } else {
            mostrarNotificacion(resultado.error, 'error');
        }
    };

    // Editar nombre
    const handleGuardarNombre = async () => {
        if (!nuevoNombre.trim()) {
            mostrarNotificacion('El nombre no puede estar vacío', 'error');
            return;
        }

        const resultado = await actualizarPerfilYStorage({ 
            nom_usuario: nuevoNombre.trim() 
        });

        if (resultado.success) {
            setEditandoNombre(false);
            mostrarNotificacion('Nombre actualizado correctamente');
        } else {
            mostrarNotificacion(resultado.error, 'error');
        }
    };

    const handleCancelarNombre = () => {
        setEditandoNombre(false);
        setNuevoNombre(usuarioLogeado.perfil?.nom_usuario || '');
    };

    // Editar descripción
    const handleGuardarDescripcion = async () => {
        const resultado = await actualizarPerfilYStorage({ 
            biografia: nuevaDescripcion.trim() 
        });

        if (resultado.success) {
            setEditandoDescripcion(false);
            mostrarNotificacion('Descripción actualizada correctamente');
        } else {
            mostrarNotificacion(resultado.error, 'error');
        }
    };

    const handleCancelarDescripcion = () => {
        setEditandoDescripcion(false);
        setNuevaDescripcion(usuarioLogeado.perfil?.biografia || '');
    };

    const handleEliminarDescripcion = async () => {
        if (!window.confirm('¿Estás seguro de eliminar tu descripción?')) return;

        const resultado = await actualizarPerfilYStorage({ 
            biografia: '' 
        });

        if (resultado.success) {
            setNuevaDescripcion('');
            mostrarNotificacion('Descripción eliminada correctamente');
        } else {
            mostrarNotificacion(resultado.error, 'error');
        }
    };

    // =============================
    // FILTRADO DE CONTENIDO
    // =============================
    const getContenidoFiltrado = useCallback(() => {
        let contenido = [];

        if (activeTab === 'publicaciones') {
            contenido = posts;
        } else if (activeTab === 'comentarios') {
            contenido = comentarios;
        } else if (activeTab === 'todo') {
            contenido = [...posts, ...comentarios].sort((a, b) => {
                const fechaA = new Date(a.fecha_pub || a.fecha_com);
                const fechaB = new Date(b.fecha_pub || b.fecha_com);
                return fechaB - fechaA;
            });
        }

        if (selectedDate) {
            const filterDate = new Date(selectedDate);
            contenido = contenido.filter(item => {
                const itemDate = new Date(item.fecha_pub || item.fecha_com);
                return itemDate.toDateString() === filterDate.toDateString();
            });
        }

        if (selectedTablon) {
            console.log("Filtro de tablón seleccionado:", selectedTablon);
        }

        return contenido;
    }, [activeTab, posts, comentarios, selectedDate, selectedTablon]);

    // =============================
    // RENDER HELPERS
    // =============================
    const renderItem = useCallback((item) => (
        <div key={`${item.tipo}-${item.id}`} className="blog-post">
            <div className="post-perf">
                <div className="info-main">
                    <img
                        className="ima-inf"
                        src={item.avatar}
                        alt={`avatar de ${item.author}`}
                    />
                    <h6 className="nombre">{item.author}</h6>
                    <h6 className="public">
                        {item.tipo === 'comentario' ? 'Comentó' : 'Publicó'}
                    </h6>
                    <h6 className="fecha">{item.date}</h6>
                </div>

                <div className="post">
                    <p>{item.content || item.text}</p>
                </div>

                {item.image && (
                    <div className="post-ima">
                        <img
                            className="ima-pub"
                            src={item.image}
                            alt="imagen del post"
                        />
                    </div>
                )}

                <div className="opciones-botton">
                    <a className="check" href="#">
                        [check]
                    </a>
                    <button className="kudos">
                        <i className="bi bi-bug-fill"></i>
                        <span style={{ marginLeft: '5px', fontSize: '12px' }}>
                            {item.kudos || 0}
                        </span>
                    </button>
                    <div className="edit-buttons">
                        <button className="edit">
                            <i className="bi bi-pencil-square"></i>
                        </button>
                        <button className="delet">
                            <i className="bi bi-trash3"></i>
                        </button>
                    </div>
                </div>
            </div>
        </div>
    ), []);

    const renderContenido = useCallback(() => {
        if (loading) {
            return (
                <div className="edit-sin-datos">
                    <p>Cargando...</p>
                </div>
            );
        }

        if (error) {
            return (
                <div className="edit-sin-datos" style={{ color: 'red' }}>
                    <p>{error}</p>
                </div>
            );
        }

        const contenido = getContenidoFiltrado();

        if (contenido.length === 0) {
            const mensaje = activeTab === 'comentarios' 
                ? 'comentarios' 
                : activeTab === 'publicaciones' 
                    ? 'publicaciones' 
                    : 'contenido';

            return (
                <div className="edit-sin-datos">
                    <p>No hay {mensaje} para mostrar</p>
                </div>
            );
        }

        return (
            <div className="all-post">
                {contenido.map(renderItem)}
            </div>
        );
    }, [loading, error, activeTab, getContenidoFiltrado, renderItem]);

    // =============================
    // RENDERIZADO PRINCIPAL
    // =============================
    if (!usuarioLogeado) {
        return (
            <div className='editar-grid'>
                <Base_AsideIZ usuario={null} />
                <Base_Main tituloPagina="Editar Perfil">
                    <div className="edit-main-content">
                        <p>Cargando...</p>
                    </div>
                </Base_Main>
                <Base_AsideDE />
            </div>
        );
    }

    return (
        <div className='editar-grid'>
            <Base_AsideIZ usuario={usuarioLogeado} />

            <Base_Main tituloPagina="Editar Perfil">
                {/* Sistema de Notificaciones */}
                {notificacion.visible && (
                    <div className={`notificacion notificacion-${notificacion.tipo}`}>
                        {notificacion.mensaje}
                    </div>
                )}

                <div className="edit-main-content">
                    {/* === PERFIL === */}
                    <div className="edit-cont-perfil">
                        <div className="edit-ima-perf">
                            <img 
                                src={imagenPreview || usuarioLogeado.perfil?.foto_perfil || IMAGEN_DEFAULT} 
                                alt="foto de perfil" 
                            />
                            <input 
                                type="file" 
                                id="input-imagen" 
                                accept="image/*"
                                style={{ display: 'none' }}
                                onChange={handleCambiarImagen}
                                disabled={guardando}
                            />
                            <button 
                                className="edit" 
                                onClick={() => document.getElementById('input-imagen').click()}
                                disabled={guardando}
                                title="Editar imagen"
                            >
                                <i className="bi bi-pencil-square"></i>
                            </button>
                            <button 
                                className="delet"
                                onClick={handleEliminarImagen}
                                disabled={guardando}
                                title="Eliminar imagen"
                            >
                                <i className="bi bi-trash3"></i>
                            </button>
                        </div>

                        <div className="edit-descrip-perf">
                            {/* NOMBRE */}
                            <div className="edit-nom">
                                {editandoNombre ? (
                                    <>
                                        <input 
                                            type="text"
                                            value={nuevoNombre}
                                            onChange={(e) => setNuevoNombre(e.target.value)}
                                            disabled={guardando}
                                            style={{
                                                fontSize: '1.5rem',
                                                padding: '5px',
                                                marginRight: '10px',
                                                flex: 1
                                            }}
                                        />
                                        <button 
                                            className="edit"
                                            onClick={handleGuardarNombre}
                                            disabled={guardando}
                                            title="Guardar"
                                        >
                                            <i className="bi bi-check-lg"></i>
                                        </button>
                                        <button 
                                            className="delet"
                                            onClick={handleCancelarNombre}
                                            disabled={guardando}
                                            title="Cancelar"
                                        >
                                            <i className="bi bi-x-lg"></i>
                                        </button>
                                    </>
                                ) : (
                                    <>
                                        <h2>
                                            {usuarioLogeado.perfil?.nom_usuario || usuarioLogeado.usuario?.nombre}
                                        </h2>
                                        <button 
                                            className="edit"
                                            onClick={() => setEditandoNombre(true)}
                                            disabled={guardando}
                                            title="Editar nombre"
                                        >
                                            <i className="bi bi-pencil-square"></i>
                                        </button>
                                    </>
                                )}
                            </div>

                            {/* DESCRIPCIÓN */}
                            <div className="edit-desc">
                                {editandoDescripcion ? (
                                    <>
                                        <textarea 
                                            value={nuevaDescripcion}
                                            onChange={(e) => setNuevaDescripcion(e.target.value)}
                                            disabled={guardando}
                                            rows="4"
                                            style={{
                                                width: '100%',
                                                padding: '10px',
                                                marginBottom: '10px',
                                                resize: 'vertical'
                                            }}
                                            placeholder="Escribe tu biografía..."
                                        />
                                        <div className="edit-desc-buttons">
                                            <button 
                                                className="edit"
                                                onClick={handleGuardarDescripcion}
                                                disabled={guardando}
                                                title="Guardar"
                                            >
                                                <i className="bi bi-check-lg"></i>
                                            </button>
                                            <button 
                                                className="delet"
                                                onClick={handleCancelarDescripcion}
                                                disabled={guardando}
                                                title="Cancelar"
                                            >
                                                <i className="bi bi-x-lg"></i>
                                            </button>
                                        </div>
                                    </>
                                ) : (
                                    <>
                                        <p>{usuarioLogeado.perfil?.biografia || "Sin biografía disponible"}</p>
                                        <div className="edit-desc-buttons">
                                            <button 
                                                className="edit"
                                                onClick={() => setEditandoDescripcion(true)}
                                                disabled={guardando}
                                                title="Editar descripción"
                                            >
                                                <i className="bi bi-pencil-square"></i>
                                            </button>
                                            <button 
                                                className="delet"
                                                onClick={handleEliminarDescripcion}
                                                disabled={guardando}
                                                title="Eliminar descripción"
                                            >
                                                <i className="bi bi-trash3"></i>
                                            </button>
                                        </div>
                                    </>
                                )}
                            </div>
                        </div>
                    </div>

                    <hr />

                    {/* === CONFIGURACIÓN DE PÁGINA === */}
                    <div className="edit-page">
                        <h5>Página</h5>
                        <div className="edit-color-page">
                            <label>Color de página: </label>
                            <div>
                                <button>Editar</button>
                                <button>Borrar</button>
                            </div>
                        </div>
                        <div className="edit-color-fondo">
                            <label>Color de fondo: </label>
                            <div>
                                <button>Editar</button>
                                <button>Borrar</button>
                            </div>
                        </div>
                        <div className="edit-image-fondo">
                            <label>Imagen de fondo: </label>
                            <div>
                                <button>Editar</button>
                                <button>Borrar</button>
                            </div>
                        </div>
                        <div className="edit-tipo-font">
                            <label>Tipo de letra: </label>
                            <div>
                                <button>Editar</button>
                                <button>Borrar</button>
                            </div>
                        </div>
                        <div className="edit-tam">
                            <label>Tamaño de letra: </label>
                            <input
                                type="range"
                                id="tam-font"
                                name="tam-font"
                                min="0"
                                max="40"
                                defaultValue="13"
                            />
                        </div>
                    </div>

                    <hr />

                    {/* === POSTS / COMENTARIOS === */}
                    <div className="edit-com-post">
                        <h5>Post / Comentario</h5>

                        <div className="edit-tap">
                            <select 
                                name="opcion-tab" 
                                id="opcion-tab" 
                                value={selectedTablon}
                                onChange={(e) => setSelectedTablon(e.target.value)}
                            >
                                <option value="">Todos los tablones</option>
                                {menuItems.slice(1).map((item) => (
                                    <option key={item.id} value={item.id}>
                                        {item.label}
                                    </option>
                                ))}
                            </select>
                            <input
                                type="date"
                                id="fecha"
                                name="fecha"
                                min="2025-01-01"
                                max="2030-12-31"
                                value={selectedDate}
                                onChange={(e) => setSelectedDate(e.target.value)}
                            />
                        </div>

                        <div className="edit-pest">
                            <button 
                                data-tab="comentarios" 
                                className={activeTab === 'comentarios' ? 'active' : ''}
                                onClick={() => setActiveTab('comentarios')}
                            >
                                Comentarios ({comentarios.length})
                            </button>
                            <button 
                                data-tab="publicaciones"
                                className={activeTab === 'publicaciones' ? 'active' : ''}
                                onClick={() => setActiveTab('publicaciones')}
                            >
                                Publicaciones ({posts.length})
                            </button>
                            <button 
                                data-tab="todo"
                                className={activeTab === 'todo' ? 'active' : ''}
                                onClick={() => setActiveTab('todo')}
                            >
                                Todo ({posts.length + comentarios.length})
                            </button>
                        </div>

                        <div className="content-edit">
                            <div className="tab-content activate">
                                {renderContenido()}
                            </div>
                        </div>
                    </div>
                </div>
            </Base_Main>

            <Base_AsideDE />
        </div>
    );
};

export default EditarPerfil;
